<script setup>
import {ref,watch} from 'vue';
import AppDialog from './AppDialog.vue';
import FormField from './FormField.vue';
import {t,number,errorText} from '../i18n';
const props=defineProps({impact:{type:Object,required:true},busy:Boolean,stale:Boolean,error:String}),emit=defineEmits(['back','confirm','refresh']);
const carry=ref(false);watch(()=>props.impact,()=>carry.value=false);
const amount=(value,unit='')=>value===null||value===undefined?t('unknown'):`${number(value,6)} ${unit}`.trim();
const stitches=value=>value?t('revisionCounts',{full:number(value.full),half:number(value.half),back:number(value.backstitch??value.back)}):t('unknown');
const dimension=(value,a,b)=>value?`${number(value[a],3)} × ${number(value[b],3)} cm`:t('unknown');
const identity=row=>[row.color.brand,row.color.range,row.color.code,row.name].filter(Boolean).join(' · ');
</script>
<template>
<AppDialog :title="t('revisionImpactTitle')" wide :busy="busy" @close="emit('back')">
 <p class="notice">{{t('revisionImpactHelp')}}</p>
 <p v-if="error" role="alert" class="notice error">{{error}}</p>
 <p v-if="stale" role="alert" class="notice warning">{{t('revision_review_stale')}}</p>
 <div class="form-grid"><section v-for="side in ['before','after']" :key="side" class="panel"><div class="panel-heading"><h3>{{t(side==='before'?'revisionCurrent':'revisionTarget')}}</h3></div><div class="panel-body"><p>{{impact[side].name||t('noPattern')}} · {{impact[side].revisionName||t('unknown')}}</p><div class="stat-row"><span>{{t('stitches')}}</span><strong>{{stitches(impact[side].counts)}}</strong></div><div class="stat-row"><span>{{t('designFullGrid')}}</span><strong>{{impact[side].width===null?t('unknown'):`${impact[side].width} × ${impact[side].height}`}}<small class="cell-subtitle">{{dimension(impact[side].dimensions?.grid,'widthCm','heightCm')}}</small></strong></div><div class="stat-row"><span>{{t('designStitchedExtent')}}</span><strong>{{impact[side].counts?.total===0?t('designEmptyExtent'):dimension(impact[side].dimensions?.stitched,'widthCm','heightCm')}}</strong></div><div class="stat-row"><span>{{t('cutSize')}}</span><strong>{{dimension(impact[side].dimensions?.grid,'cutWidthCm','cutHeightCm')}}</strong></div></div></section></div>
 <p class="field-help">{{t('revisionPrintHelp',{paper:impact.paper?.toUpperCase()||t('unknown')})}}</p>
 <h3>{{t('revisionProgressTitle')}}</h3><p>{{t('revisionProgressHelp',{completed:number(impact.completed),matched:number(impact.progress.matched),unmatched:number(impact.progress.unmatched),markers:number(impact.markers)})}}</p><p v-if="impact.manualPercent||impact.referenceAnnotations" class="notice warning">{{t('revisionManualHelp',{percent:number(impact.manualPercent),annotations:number(impact.referenceAnnotations)})}}</p>
 <FormField :label="t('revisionCarry')" :help="t('revisionCarryHelp')" v-slot="{id,describedby}"><input :id="id" v-model="carry" :aria-describedby="describedby" type="checkbox" :disabled="busy||stale||!impact.progress.eligible||!impact.progress.matched"/></FormField>
 <p v-for="side in ['before','after'].filter(key=>impact.estimateErrors[key])" :key="side" class="field-help">{{t(side==='before'?'revisionCurrent':'revisionTarget')}}: {{errorText({code:impact.estimateErrors[side]})}}</p><h3>{{t('revisionMaterialTitle')}}</h3><p class="notice warning">{{t('revisionNeedsHelp',{removed:number(impact.derivedNeeds),retained:number(impact.retainedNeeds),reservations:number(impact.reservationCount),regions:number(impact.fabricRegions.length)})}}</p><p class="field-help">{{t('revisionEstimateHelp')}}</p><p v-if="impact.estimateErrors.before||impact.estimateErrors.after" class="notice">{{t('revisionEstimateUnknown')}}</p>
 <div v-if="impact.materials.length" class="table-wrap"><table><thead><tr><th>{{t('material')}}</th><th>{{t('revisionUse')}}</th><th>{{t('revisionSuggested')}}</th></tr></thead><tbody><tr v-for="row in impact.materials" :key="row.key"><td>{{identity(row)}}<span v-if="!row.materialId" class="badge warning">{{t('revisionUnmapped')}}</span></td><td>{{stitches(row.beforeCounts)}}<span class="cell-subtitle">› {{stitches(row.afterCounts)}}</span></td><td>{{amount(row.beforeEstimate.quantity,row.unit)}} › {{amount(row.afterEstimate.quantity,row.unit)}}<span class="cell-subtitle">{{amount(row.beforeEstimate.filamentMetres,'strand-m')}} › {{amount(row.afterEstimate.filamentMetres,'strand-m')}}</span></td></tr></tbody></table></div>
 <h3 v-if="impact.materials.length">{{t('revisionSavedNeeds')}}</h3><div v-if="impact.materials.length" class="table-wrap"><table><thead><tr><th>{{t('material')}}</th><th>{{t('revisionCurrent')}} › {{t('revisionTarget')}}</th><th>{{t('reserved')}}</th><th>{{t('consumed')}}</th></tr></thead><tbody><tr v-for="row in impact.materials" :key="row.key"><td>{{identity(row)}}</td><td>{{amount(row.needBefore,row.unit)}} › {{amount(row.needAfter,row.unit)}}<span v-if="row.removedNeeds" class="cell-subtitle">{{t('revisionArchivedNeed')}}</span></td><td>{{row.reservations===null?t('unknown'):row.reservations.length?row.reservations.map(r=>amount(r.quantity,r.unit)).join(' + '):amount(0,row.unit)}}</td><td>{{amount(row.consumed,row.unit)}}</td></tr></tbody></table></div>
 <p v-if="impact.oldEstimateArchived" class="field-help">{{t('revisionEstimateArchived')}}</p><p v-if="impact.manualForecastRetained" class="notice">{{t('revisionForecastReview')}}</p>
 <template #footer><button class="button" :disabled="busy" @click="emit('back')">{{t('back')}}</button><button v-if="stale" class="button" :disabled="busy" @click="emit('refresh')">{{t('revisionRefresh')}}</button><button class="button primary" :disabled="busy||stale" @click="emit('confirm',carry)">{{t('revisionApply')}}</button></template>
</AppDialog>
</template>
